/**
 * Keep tracked sessions portable: rewrite the session header's cwd to ".".
 *
 * Pi writes an absolute cwd into every session header and hides any session whose
 * header does not resolve to the directory pi runs from. This repo syncs
 * .pi/sessions between a Windows and a Linux checkout, so absolute headers make
 * sessions invisible on the other machine. Pi resolves a *relative* header cwd
 * against the launch directory, so "." matches everywhere.
 *
 * Pi has no hook for the header itself, so this patches the session module's
 * SessionManager prototype - the same class object main.js imported, because the
 * extension loader resolves it from the app's node_modules. If a future pi
 * version changes the module layout, the extension reports it and does nothing.
 *
 * Disable with: pi -ne   (or remove this file)
 */

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join, relative, resolve } from "node:path";

const RELATIVE_CWD = ".";

type Headerish = { type?: string; cwd?: string; version?: number };
type ManagerLike = {
	getSessionFile?: () => string | undefined;
	getCwd?: () => string;
};

function projectRoot(): string {
	// Session dir is <root>/.pi/sessions; walk up to the directory holding .pi.
	let dir = resolve(process.cwd());
	for (let depth = 0; depth < 6; depth++) {
		if (existsSync(join(dir, ".pi", "settings.json"))) return dir;
		const up = dirname(dir);
		if (up === dir) break;
		dir = up;
	}
	return resolve(process.cwd());
}

/** "." when the session lives under the project, else the original absolute path. */
function portableCwd(cwd: string, root: string): string {
	const rel = relative(root, resolve(cwd));
	if (rel === "") return RELATIVE_CWD;
	if (rel === ".." || rel.startsWith(`..${process.platform === "win32" ? "\\" : "/"}`) || rel.startsWith("/")) {
		return cwd; // Outside the project: an absolute path is the honest value.
	}
	return RELATIVE_CWD;
}

function rewriteHeader(filePath: string, root: string): void {
	try {
		const data = readFileSync(filePath, "utf8");
		const end = data.indexOf("\n");
		if (end <= 0) return;
		let header: Headerish;
		try {
			header = JSON.parse(data.slice(0, end)) as Headerish;
		} catch {
			return;
		}
		if (header.type !== "session" || !header.cwd) return;
		const next = portableCwd(header.cwd, root);
		if (next === header.cwd) return;
		// Replace only the cwd value so every other byte of the header survives.
		const line = data.slice(0, end).replace(/("cwd"\s*:\s*)"(?:[^"\\]|\\.)*"/, (_m, k) => `${k}${JSON.stringify(next)}`);
		writeFileSync(filePath, line + "\n" + data.slice(end + 1));
	} catch {
		// A header we cannot parse is not ours to rewrite.
	}
}

function install(root: string, report: (msg: string) => void): void {
	const dir = dirname(process.argv[1] ?? "");
	const require = createRequire(join(dir, "noop.cjs"));
	let mod: { SessionManager?: { prototype: Record<string, unknown> } };
	try {
		mod = require("@earendil-works/pi-coding-agent/dist/core/session-manager.js") as typeof mod;
	} catch {
		report("session module path changed; session cwd left absolute");
		return;
	}
	const proto = mod?.SessionManager?.prototype;
	if (!proto) {
		report("SessionManager prototype missing; session cwd left absolute");
		return;
	}
	for (const name of ["newSession", "flush"] as const) {
		const original = proto[name];
		if (typeof original !== "function") continue;
		Object.defineProperty(proto, name, {
			configurable: true,
			writable: true,
			value: function patched(this: ManagerLike & Record<string, unknown>, ...args: unknown[]) {
				const result = (original as (...a: unknown[]) => unknown).apply(this, args);
				// Header is line 1, so rewriting it cannot race an end-of-file append.
				const file = this.getSessionFile?.();
				if (file) rewriteHeader(file, root);
				return result;
			},
		});
	}
}

export default function (pi: { on: (event: string, handler: (e: unknown, ctx: unknown) => void) => void }): void {
	const root = projectRoot();
	let reported = false;
	const report = (msg: string) => {
		if (reported) return;
		reported = true;
		queueMicrotask(() => pi.notify?.(msg, "warning"));
	};
	install(root, report);
	// Covers sessions opened before this extension loaded, and files synced in
	// from the other machine while pi was running.
	pi.on("session_start", (_event: unknown, ctx: unknown) => {
		const manager = (ctx as { sessionManager?: ManagerLike })?.sessionManager;
		const file = manager?.getSessionFile?.();
		if (file) rewriteHeader(file, root);
	});
}
EOF
