/**
 * Portable session cwd for a repo that syncs .pi/sessions across machines.
 *
 * Pi writes an absolute cwd into every session header and hides any session whose
 * header does not resolve to the directory pi is running from. This checkout
 * exists on both Windows (C:\Projects\Embedded-Pi) and Linux
 * (/home/vial/projects/Embedded-Pi), so absolute headers make sessions written on
 * the other machine invisible in the resume picker.
 *
 * Pi resolves a *relative* header cwd against the launch directory, so "." matches
 * on every machine. This extension rewrites the header before it reaches disk by
 * patching SessionManager._persist / ._rewriteFile - the same class object the app
 * holds, because the extension loader aliases the package root to the running
 * module. Pi exposes no header hook, so patching is the only supported surface.
 *
 * Verified against pi 1.2.0. If a future version drops those methods the patch
 * installs nothing and says so once via a warning notification.
 *
 * Disable for one run: pi -ne
 */

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { SessionManager } from "@earendil-works/pi-coding-agent";

/** Header cwd that resolves to the project on any machine. */
const RELATIVE_CWD = ".";
/** Session files live under <root>/.pi/sessions; walk up looking for this. */
const PROJECT_MARKER = join(".pi", "settings.json");

type Header = { type?: string; cwd?: string };
type Manager = {
	fileEntries?: Array<{ type?: string; cwd?: string }>;
	getSessionFile?: () => string | undefined;
};

function findProjectRoot(): string {
	let dir = resolve(process.cwd());
	for (let depth = 0; depth < 6; depth++) {
		if (existsSync(join(dir, PROJECT_MARKER))) return dir;
		const parent = dirname(dir);
		if (parent === dir) break;
		dir = parent;
	}
	return resolve(process.cwd());
}

/**
 * "." when the recorded cwd is the project itself, otherwise the original value.
 * Sessions started outside the project keep an absolute cwd - "." would be a lie.
 */
function portableCwd(cwd: string | undefined, root: string): string | undefined {
	if (!cwd) return cwd;
	const resolved = resolve(cwd);
	if (resolved === root) return RELATIVE_CWD;
	const rel = relative(root, resolved);
	const escapes = rel === ".." || rel.startsWith("..") || rel.startsWith("/") || /^[A-Za-z]:[\\/]/.test(rel);
	return escapes ? cwd : RELATIVE_CWD;
}

function normalizeInMemoryHeader(manager: Manager, root: string): void {
	const header = manager.fileEntries?.[0];
	if (!header || header.type !== "session" || !header.cwd) return;
	const next = portableCwd(header.cwd, root);
	if (next !== undefined) header.cwd = next;
}

/** Rewrite line 1 of an already-written session file, preserving all other bytes. */
function rewriteHeaderOnDisk(filePath: string, root: string): void {
	try {
		const data = readFileSync(filePath, "utf8");
		const end = data.indexOf("\n");
		if (end <= 0) return;
		let header: Header;
		try {
			header = JSON.parse(data.slice(0, end)) as Header;
		} catch {
			return;
		}
		if (header.type !== "session" || !header.cwd) return;
		const next = portableCwd(header.cwd, root);
		if (next === undefined || next === header.cwd) return;
		const line = data
			.slice(0, end)
			.replace(/("cwd"\s*:\s*)"(?:[^"\\]|\\.)*"/, (_match, key: string) => `${key}${JSON.stringify(next)}`);
		writeFileSync(filePath, line + data.slice(end));
	} catch {
		// Unreadable or concurrently written: leave it alone, the next start retries.
	}
}

function installPatch(root: string, report: (message: string) => void): boolean {
	const proto = SessionManager.prototype as unknown as Record<string, unknown>;
	const persist = proto._persist;
	const rewriteFile = proto._rewriteFile;
	if (typeof persist !== "function" || typeof rewriteFile !== "function") {
		report("pi internals changed (_persist/_rewriteFile); session cwd stays absolute");
		return false;
	}

	const patchedPersist = function (this: Manager, ...args: unknown[]) {
		// _persist writes fileEntries on first flush and appends afterwards, so
		// normalizing the in-memory header covers both paths.
		normalizeInMemoryHeader(this, root);
		return (persist as (...a: unknown[]) => unknown).apply(this, args);
	};
	const patchedRewrite = function (this: Manager, ...args: unknown[]) {
		normalizeInMemoryHeader(this, root);
		return (rewriteFile as (...a: unknown[]) => unknown).apply(this, args);
	};
	// Both prototype keys are writable; assign so a reload re-patches cleanly.
	proto._persist = patchedPersist;
	proto._rewriteFile = patchedRewrite;
	return true;
}

export default function (pi: {
	on: (event: "session_start", handler: (event: unknown, ctx: unknown) => void) => void;
	notify?: (message: string, type?: "info" | "warning" | "error") => void;
}): void {
	const root = findProjectRoot();
	let reported = false;
	const report = (message: string) => {
		if (reported || !pi.notify) return;
		reported = true;
		pi.notify(message, "warning");
	};

	const patched = installPatch(root, report);

	// Covers sessions opened before the patch existed, files synced in from the
	// other machine, and the case where the patch could not install.
	pi.on("session_start", (_event, ctx) => {
		const manager = (ctx as { sessionManager?: Manager } | undefined)?.sessionManager;
		const file = manager?.getSessionFile?.();
		if (file) rewriteHeaderOnDisk(file, root);
		if (!patched && !reported) report("session cwd patched only on open; new sessions stay absolute");
	});
}

